4	module host_inter(
5	  input                            clk                ,
6	  input                            rst_n              ,
7	  input                            s_axilite_awready_o, 
8	  output                           s_axilite_awvalid_i,
9	  output [`AXILITE_ADDR_WIDTH-1:0] s_axilite_awaddr_i ,
10	  output [`AXILITE_PROT_WIDTH-1:0] s_axilite_awprot_i ,
11	                                               
12	  input                            s_axilite_wready_o ,
13	  output                           s_axilite_wvalid_i ,
14	  output [`AXILITE_DATA_WIDTH-1:0] s_axilite_wdata_i  ,
15	  output [`AXILITE_STRB_WIDTH-1:0] s_axilite_wstrb_i  ,
16	                                               
17	  output                           s_axilite_bready_i ,
18	  input                            s_axilite_bvalid_o ,
19	  input  [`AXILITE_RESP_WIDTH-1:0] s_axilite_bresp_o  ,
20	                                               
21	  input                            s_axilite_arready_o,
22	  output                           s_axilite_arvalid_i,
23	  output [`AXILITE_ADDR_WIDTH-1:0] s_axilite_araddr_i ,
24	  output [`AXILITE_PROT_WIDTH-1:0] s_axilite_arprot_i ,
25	                                               
26	  output                           s_axilite_rready_i ,
