32	  //--------------------------------------------------------------------------------
33	  reg                           s_axilite_awvalid_r;
34	  reg [`AXILITE_ADDR_WIDTH-1:0] s_axilite_awaddr_r ;
35	  reg [`AXILITE_PROT_WIDTH-1:0] s_axilite_awprot_r ;
36	  reg                           s_axilite_wvalid_r ;
37	  reg [`AXILITE_DATA_WIDTH-1:0] s_axilite_wdata_r  ;
38	  reg [`AXILITE_STRB_WIDTH-1:0] s_axilite_wstrb_r  ;
39	  reg                           s_axilite_bready_r ;
40	  reg                           s_axilite_arvalid_r;
41	  reg [`AXILITE_ADDR_WIDTH-1:0] s_axilite_araddr_r ;
42	  reg [`AXILITE_PROT_WIDTH-1:0] s_axilite_arprot_r ;
43	  reg                           s_axilite_rready_r ;
44	
45	  assign s_axilite_awvalid_i = s_axilite_awvalid_r;
46	  assign s_axilite_awaddr_i  = s_axilite_awaddr_r;
47	  assign s_axilite_awprot_i  = s_axilite_awprot_r;
48	  assign s_axilite_wvalid_i  = s_axilite_wvalid_r;
49	  assign s_axilite_wdata_i   = s_axilite_wdata_r;
50	  assign s_axilite_wstrb_i   = s_axilite_wstrb_r;
51	  assign s_axilite_bready_i  = s_axilite_bready_r;
52	  assign s_axilite_arvalid_i = s_axilite_arvalid_r;
53	  assign s_axilite_araddr_i  = s_axilite_araddr_r;
54	  assign s_axilite_arprot_i  = s_axilite_arprot_r;
55	  assign s_axilite_rready_i  = s_axilite_rready_r;
56	
57	  initial begin
58	    s_axilite_awvalid_r = 1'd0;
59	    s_axilite_awaddr_r  = {`AXILITE_ADDR_WIDTH{1'd0}};
60	    s_axilite_awprot_r  = {`AXILITE_PROT_WIDTH{1'd0}};
61	    s_axilite_wvalid_r  = 1'd0;
62	    s_axilite_wdata_r   = {`AXILITE_DATA_WIDTH{1'd0}};
63	    s_axilite_wstrb_r   = {`AXILITE_STRB_WIDTH{1'd0}};
64	    s_axilite_bready_r  = 1'd1; //write response channel always ready
65	    s_axilite_arvalid_r = 1'd0;
66	    s_axilite_araddr_r  = {`AXILITE_ADDR_WIDTH{1'd0}};
67	    s_axilite_arprot_r  = {`AXILITE_PROT_WIDTH{1'd0}};
68	    s_axilite_rready_r  = 1'd1; //read data channel always ready
69	  end
70	
71	  parameter META_FNAME_SIZE = 128;
72	  parameter METADATA_SIZE   = 500;
73	
74	  parameter DATA_FNAME_SIZE = 128;
75	  parameter DATADATA_SIZE   = 500;
76	  
77	  reg [31:0] metadata [METADATA_SIZE-1:0];
78	  reg [31:0] parsed_base_r  [0:10-1];
79	  reg [31:0] parsed_size_r  [0:10-1];
80	
81	  reg [31:0] cycle_count  [0:2-1];
82	  reg [31:0] kernel_cycles       ;
