84	  task drv_gpu;
85	    input [META_FNAME_SIZE*8-1:0] fn_metadata;
86	    input [DATA_FNAME_SIZE*8-1:0] fn_data;
87	    reg [31:0] block_id = 0;
88	    reg [63:0] noused;
89	    reg [63:0] kernel_id;
90	    reg [63:0] kernal_size0;
91	    reg [63:0] kernal_size1;
92	    reg [63:0] kernal_size2;
93	    reg [63:0] wf_size;
94	    reg [63:0] wg_size;
95	    reg [63:0] metaDataBaseAddr;
96	    reg [63:0] ldsSize;
97	    reg [63:0] pdsSize;
98	    reg [63:0] sgprUsage;
99	    reg [63:0] vgprUsage;
100	    reg [63:0] pdsBaseAddr;
101	    reg [63:0] num_buffer;
102	    reg [31:0] pds_size;
103	    begin
104	      $readmemh(fn_metadata, metadata);
105	      $display("============================================");
106	      $display("*********");
107	      $display("Begin test:");
108	      $display("metadata is %s:", fn_metadata);
109	      $display("data is %s:", fn_data);
110	      $display("*********");
111	      $display("");
112	      @(posedge clk);
113	      noused           = {metadata[ 1], metadata[ 0]};
114	      kernel_id        = {metadata[ 3], metadata[ 2]}; 
115	      kernal_size0     = {metadata[ 5], metadata[ 4]}; 
116	      kernal_size1     = {metadata[ 7], metadata[ 6]}; 
117	      kernal_size2     = {metadata[ 9], metadata[ 8]}; 
118	      wf_size          = {metadata[11], metadata[10]}; 
119	      wg_size          = {metadata[13], metadata[12]}; 
120	      metaDataBaseAddr = {metadata[15], metadata[14]}; 
121	      ldsSize          = {metadata[17], metadata[16]}; 
122	      pdsSize          = {metadata[19], metadata[18]}; 
123	      sgprUsage        = {metadata[21], metadata[20]}; 
124	      vgprUsage        = {metadata[23], metadata[22]}; 
125	      pdsBaseAddr      = {metadata[25], metadata[24]}; 
126	      num_buffer       = {metadata[27], metadata[26]}; 
127	      pds_size         = 32'd0;
128	      //host to cta
129	      @(posedge clk);
130	      axilite_write(32'h0000_0004,{`WG_ID_WIDTH{1'd0}}); //reg[1] host_req_wg_id
131	      @(posedge clk);
132	      axilite_write(32'h0000_0008,wg_size[31:0]); //reg[2] host_req_num_wf
133	      @(posedge clk);
134	      axilite_write(32'h0000_000c,wf_size[31:0]); //reg[3] host_req_wf_size
135	      @(posedge clk);
136	      axilite_write(32'h0000_0010,32'h8000_0000); //reg[4] host_req_start_pc
137	      @(posedge clk);
138	      axilite_write(32'h0000_0014,wg_size[31:0]*vgprUsage[31:0]); //reg[5] host_req_vgpr_size_total
139	      @(posedge clk);
140	      axilite_write(32'h0000_0018,wg_size[31:0]*sgprUsage[31:0]); //reg[6] host_req_sgpr_size_total
141	      @(posedge clk);
142	      axilite_write(32'h0000_001c,32'd128); //reg[7] host_req_lds_size_total
143	      @(posedge clk);
144	      axilite_write(32'h0000_0020,vgprUsage[31:0]); //reg[8] host_req_vgpr_size_per_wf
145	      @(posedge clk);
146	      axilite_write(32'h0000_0024,sgprUsage[31:0]); //reg[9] host_req_sgpr_size_per_wf
147	      @(posedge clk);
148	      axilite_write(32'h0000_0028,32'h0); //reg[10] host_req_gds_baseaddr
149	      @(posedge clk);
150	      axilite_write(32'h0000_002c,pdsBaseAddr[31:0]+block_id*pds_size*wf_size[31:0]*wg_size[31:0]); //reg[11] host_req_pds_baseaddr
151	      @(posedge clk);
152	      axilite_write(32'h0000_0030,metaDataBaseAddr[31:0]); //reg[12] host_req_csr_knl
153	      @(posedge clk);
154	      axilite_write(32'h0000_0034,32'h0); //reg[13] host_req_kernel_size_3d
155	      @(posedge clk);
156	      axilite_write(32'h0000_0038,32'h0); //reg[14] host_req_kernel_size_3d
157	      @(posedge clk);
158	      axilite_write(32'h0000_003c,32'h0); //reg[15] host_req_kernel_size_3d
159	      @(posedge clk);
160	      axilite_write(32'h0000_0000,32'd1); //reg[0] host_req_valid
161	      @(negedge test_gpu_axi_top.u_dut.gpgpu_top.cta.cta2host_rcvd_ack_o);
162	      $display("*********");
163	      $display("metadata is %s:", fn_metadata);
164	      $display("data is %s:", fn_data);
165	      $display("Config finish!  time: %t ns",$realtime);
166	      cycle_count[0] = $realtime;
167	      $display("*********");
168	      $display("");
169	    end
170	  endtask
171	
172	  task axilite_write;
173	    input [`AXILITE_ADDR_WIDTH-1:0] w_addr;
174	    input [`AXILITE_DATA_WIDTH-1:0] w_data;
175	    begin
176	      fork 
177	        begin:write_addr
178	          s_axilite_awvalid_r = 1'd1;
179	          s_axilite_awaddr_r  = w_addr; 
180	          s_axilite_awprot_r  = {`AXILITE_PROT_WIDTH{1'd0}};
181	          wait(s_axilite_awready_o);
182	          @(posedge clk);
183	          s_axilite_awvalid_r = 1'd0;
184	        end
185	        begin:write_data
186	          s_axilite_wvalid_r  = 1'd1;
187	          s_axilite_wdata_r   = w_data; 
188	          s_axilite_wstrb_r   = {`AXILITE_STRB_WIDTH{1'd1}}; 
189	          wait(s_axilite_wready_o);
190	          @(posedge clk);
191	          s_axilite_wvalid_r  = 1'd0;
192	        end
193	      join
194	    end 
195	  endtask
196	
197	  task axilite_read;
198	    input  [`AXILITE_ADDR_WIDTH-1:0] r_addr;
199	    output [`AXILITE_DATA_WIDTH-1:0] r_data;
200	    begin
201	      s_axilite_rready_r  = 1'd1; //read bus always ready
202	      s_axilite_arvalid_r = 1'd1;
203	      s_axilite_araddr_r  = r_addr;
204	      s_axilite_arprot_r  = {`AXILITE_PROT_WIDTH{1'd0}};
205	      wait(s_axilite_arready_o);
206	      @(posedge clk);
207	      s_axilite_arvalid_r = 1'd0;
208	      wait(s_axilite_rvalid_o);
209	      #1;
210	        r_data = s_axilite_rdata_o;
211	    end
212	  endtask
213	
214	  task exe_finish;
215	    input [META_FNAME_SIZE*8-1:0] fn_metadata;
216	    input [DATA_FNAME_SIZE*8-1:0] fn_data;
217	    reg [`AXILITE_DATA_WIDTH-1:0] r_data;
218	    integer i;
219	    begin
220	      i = 0;
221	      r_data=0;
222	      while(i == 0) begin
223	        wait(!s_axilite_rvalid_o)
224	        axilite_read(32'h0000_0044,r_data);
225	        @(posedge clk);
226	        if(r_data)
227	          i = 1;
228	          @(posedge clk);
229	          @(posedge clk);
230	      end
231	      $display("*********");
232	      $display("metadata is %s:", fn_metadata);
233	      $display("data is %s:", fn_data);
234	      $display("exe finish!     time: %t ns",$realtime);
235	      cycle_count[1] = $realtime;
236	      $display("*********");
237	      $display("");
238	      kernel_cycles = (cycle_count[1]-cycle_count[0])/10;
239	      $display("*********");
240	      $display("Single kernel need : %t cycles",kernel_cycles);
241	      $display("*********");
242	      $display("");
243	      $display("============================================");
244	      $display("");
245	    end
246	  endtask
247	
248	  task get_result_addr;
249	    input [META_FNAME_SIZE*8-1:0] fn_metadata;
250	    input [DATA_FNAME_SIZE*8-1:0] fn_data;
251	    reg   [31:0]                  num_buffer;
252	    integer i;
253	    begin
254	      $readmemh(fn_metadata, metadata);
255	      @(posedge clk);
256	      num_buffer          = metadata[26]; 
257	      for(i=0; i<num_buffer; i=i+1) begin
258	        parsed_base_r[i]  = metadata[28+i*2];
259	        parsed_size_r[i]  = metadata[28+i*2+num_buffer*2];
260	      end
261	    end
262	  endtask
263	
264	
265	endmodule
