11	// Author: Zhang, Qi
12	// Description:
13	
14	`resetall
15	`timescale 1ns / 1ps
16	`default_nettype none
17	
18	/*
19	 * AXI4 RAM
20	 */
21	module axi_ram #
22	  (
23	  // Width of data bus in bits
24	  parameter DATA_WIDTH = 64,
25	  // Width of address bus in bits
26	  parameter ADDR_WIDTH = 32,
27	  // Width of wstrb (width of data bus in words)
28	  parameter STRB_WIDTH = (DATA_WIDTH/8),
29	  // Width of ID signal
30	  parameter ID_WIDTH = 4,
31	  // Extra pipeline register on output
32	  parameter PIPELINE_OUTPUT = 0,
33	  //store result from mem
34	  parameter RESULT_REG_WIDTH = 127
35	  )
36	  (
37	  input  wire                   clk,
38	  input  wire                   rst,
39	
40	  input  wire [ID_WIDTH-1:0]    s_axi_awid,
41	  input  wire [ADDR_WIDTH-1:0]  s_axi_awaddr,
42	  input  wire [7:0]             s_axi_awlen,
43	  input  wire [2:0]             s_axi_awsize,
44	  input  wire [1:0]             s_axi_awburst,
45	  input  wire                   s_axi_awlock,
46	  input  wire [3:0]             s_axi_awcache,
47	  input  wire [2:0]             s_axi_awprot,
48	  input  wire                   s_axi_awvalid,
49	  output wire                   s_axi_awready,
50	  input  wire [DATA_WIDTH-1:0]  s_axi_wdata,
51	  input  wire [STRB_WIDTH-1:0]  s_axi_wstrb,
52	  input  wire                   s_axi_wlast,
53	  input  wire                   s_axi_wvalid,
54	  output wire                   s_axi_wready,
55	  output wire [ID_WIDTH-1:0]    s_axi_bid,
56	  output wire [1:0]             s_axi_bresp,
57	  output wire                   s_axi_bvalid,
58	  input  wire                   s_axi_bready,
59	  input  wire [ID_WIDTH-1:0]    s_axi_arid,
60	  input  wire [ADDR_WIDTH-1:0]  s_axi_araddr,
61	  input  wire [7:0]             s_axi_arlen,
62	  input  wire [2:0]             s_axi_arsize,
63	  input  wire [1:0]             s_axi_arburst,
64	  input  wire                   s_axi_arlock,
65	  input  wire [3:0]             s_axi_arcache,
66	  input  wire [2:0]             s_axi_arprot,
67	  input  wire                   s_axi_arvalid,
68	  output wire                   s_axi_arready,
69	  output wire [ID_WIDTH-1:0]    s_axi_rid,
70	  output wire [DATA_WIDTH-1:0]  s_axi_rdata,
71	  output wire [1:0]             s_axi_rresp,
72	  output wire                   s_axi_rlast,
73	  output wire                   s_axi_rvalid,
74	  input  wire                   s_axi_rready
75	  );
76	
77	  parameter VALID_ADDR_WIDTH = ADDR_WIDTH - $clog2(STRB_WIDTH);
78	  parameter WORD_WIDTH = STRB_WIDTH;
79	  parameter WORD_SIZE = DATA_WIDTH/WORD_WIDTH;
80	  
81	  // bus width assertions
82	  initial begin
83	    if (WORD_SIZE * STRB_WIDTH != DATA_WIDTH) begin
84	        $error("Error: AXI data width not evenly divisble (instance %m)");
85	        $finish;
86	    end
87	
88	    if (2**$clog2(WORD_WIDTH) != WORD_WIDTH) begin
89	        $error("Error: AXI word width must be even power of two (instance %m)");
90	        $finish;
91	    end
92	  end
93	
94	  localparam [0:0]
95	    READ_STATE_IDLE = 1'd0,
96	    READ_STATE_BURST = 1'd1;
97	
98	  reg [0:0] read_state_reg = READ_STATE_IDLE, read_state_next;
99	
100	  localparam [1:0]
101	    WRITE_STATE_IDLE = 2'd0,
102	    WRITE_STATE_BURST = 2'd1,
103	    WRITE_STATE_RESP = 2'd2;
104	
105	  reg [1:0] write_state_reg = WRITE_STATE_IDLE, write_state_next;
106	
107	  reg mem_wr_en;
108	  reg mem_rd_en;
109	
110	  reg [ID_WIDTH-1:0] read_id_reg = {ID_WIDTH{1'b0}}, read_id_next;
111	  reg [ADDR_WIDTH-1:0] read_addr_reg = {ADDR_WIDTH{1'b0}}, read_addr_next;
112	  reg [7:0] read_count_reg = 8'd0, read_count_next;
113	  reg [2:0] read_size_reg = 3'd0, read_size_next;
114	  reg [1:0] read_burst_reg = 2'd0, read_burst_next;
115	  reg [ID_WIDTH-1:0] write_id_reg = {ID_WIDTH{1'b0}}, write_id_next;
116	  reg [ADDR_WIDTH-1:0] write_addr_reg = {ADDR_WIDTH{1'b0}}, write_addr_next;
117	  reg [7:0] write_count_reg = 8'd0, write_count_next;
118	  reg [2:0] write_size_reg = 3'd0, write_size_next;
119	  reg [1:0] write_burst_reg = 2'd0, write_burst_next;
120	  
121	  reg s_axi_awready_reg = 1'b0, s_axi_awready_next;
122	  reg s_axi_wready_reg = 1'b0, s_axi_wready_next;
123	  reg [ID_WIDTH-1:0] s_axi_bid_reg = {ID_WIDTH{1'b0}}, s_axi_bid_next;
124	  reg s_axi_bvalid_reg = 1'b0, s_axi_bvalid_next;
125	  reg s_axi_arready_reg = 1'b0, s_axi_arready_next;
126	  reg [ID_WIDTH-1:0] s_axi_rid_reg = {ID_WIDTH{1'b0}}, s_axi_rid_next;
127	  reg [DATA_WIDTH-1:0] s_axi_rdata_reg = {DATA_WIDTH{1'b0}}, s_axi_rdata_next;
128	  reg s_axi_rlast_reg = 1'b0, s_axi_rlast_next;
129	  reg s_axi_rvalid_reg = 1'b0, s_axi_rvalid_next;
130	  reg [ID_WIDTH-1:0] s_axi_rid_pipe_reg = {ID_WIDTH{1'b0}};
131	  reg [DATA_WIDTH-1:0] s_axi_rdata_pipe_reg = {DATA_WIDTH{1'b0}};
132	  reg s_axi_rlast_pipe_reg = 1'b0;
133	  reg s_axi_rvalid_pipe_reg = 1'b0;
134	
135	  // (* RAM_STYLE="BLOCK" *)
136	  reg [DATA_WIDTH-1:0] mem [(2**VALID_ADDR_WIDTH)-1:0];
137	  //logic [DATA_WIDTH-1:0] mem [bit unsigned [(2**VALID_ADDR_WIDTH)-1:0]];
138	  
139	  wire [VALID_ADDR_WIDTH-1:0] s_axi_awaddr_valid = s_axi_awaddr >> (ADDR_WIDTH - VALID_ADDR_WIDTH);
140	  wire [VALID_ADDR_WIDTH-1:0] s_axi_araddr_valid = s_axi_araddr >> (ADDR_WIDTH - VALID_ADDR_WIDTH);
141	  wire [VALID_ADDR_WIDTH-1:0] read_addr_valid = read_addr_reg >> (ADDR_WIDTH - VALID_ADDR_WIDTH);
142	  wire [VALID_ADDR_WIDTH-1:0] write_addr_valid = write_addr_reg >> (ADDR_WIDTH - VALID_ADDR_WIDTH);
143	
144	  reg [31:0] mem_tmp_1 [127:0];
145	  reg [31:0] mem_tmp_2 [127:0];
146	  
147	  assign s_axi_awready = s_axi_awready_reg;
148	  assign s_axi_wready = s_axi_wready_reg;
149	  assign s_axi_bid = s_axi_bid_reg;
150	  assign s_axi_bresp = 2'b00;
151	  assign s_axi_bvalid = s_axi_bvalid_reg;
152	  assign s_axi_arready = s_axi_arready_reg;
153	  assign s_axi_rid = PIPELINE_OUTPUT ? s_axi_rid_pipe_reg : s_axi_rid_reg;
154	  assign s_axi_rdata = PIPELINE_OUTPUT ? s_axi_rdata_pipe_reg : s_axi_rdata_reg;
155	  assign s_axi_rresp = 2'b00;
156	  assign s_axi_rlast = PIPELINE_OUTPUT ? s_axi_rlast_pipe_reg : s_axi_rlast_reg;
157	  assign s_axi_rvalid = PIPELINE_OUTPUT ? s_axi_rvalid_pipe_reg : s_axi_rvalid_reg;
158	  
159	  integer i, j;
160	  
161	  initial begin
162	    // mem=new[2**VALID_ADDR_WIDTH];
163	    // two nested loops for smaller number of iterations per loop
164	    // workaround for synthesizer complaints about large loop counts
165	    for (i = 0; i < 2**VALID_ADDR_WIDTH; i = i + 2**(VALID_ADDR_WIDTH/2)) begin
166	        for (j = i; j < i + 2**(VALID_ADDR_WIDTH/2); j = j + 1) begin
167	            mem[j] = 0;
168	        end
169	    end
170	  end
171	  
172	  always @* begin
173	    write_state_next = WRITE_STATE_IDLE;
174	
175	    mem_wr_en = 1'b0;
176	
177	    write_id_next = write_id_reg;
178	    write_addr_next = write_addr_reg;
179	    write_count_next = write_count_reg;
180	    write_size_next = write_size_reg;
181	    write_burst_next = write_burst_reg;
182	
183	    s_axi_awready_next = 1'b0;
184	    s_axi_wready_next = 1'b0;
185	    s_axi_bid_next = s_axi_bid_reg;
186	    s_axi_bvalid_next = s_axi_bvalid_reg && !s_axi_bready;
187	
188	    case (write_state_reg)
189	        WRITE_STATE_IDLE: begin
190	            s_axi_awready_next = 1'b1;
191	
192	            if (s_axi_awready && s_axi_awvalid) begin
193	                write_id_next = s_axi_awid;
194	                write_addr_next = s_axi_awaddr;
195	                write_count_next = s_axi_awlen;
196	                write_size_next = s_axi_awsize < $clog2(STRB_WIDTH) ? s_axi_awsize : $clog2(STRB_WIDTH);
197	                write_burst_next = s_axi_awburst;
198	
199	                s_axi_awready_next = 1'b0;
200	                s_axi_wready_next = 1'b1;
201	                write_state_next = WRITE_STATE_BURST;
202	            end else begin
203	                write_state_next = WRITE_STATE_IDLE;
204	            end
205	        end
206	        WRITE_STATE_BURST: begin
207	            s_axi_wready_next = 1'b1;
208	
209	            if (s_axi_wready && s_axi_wvalid) begin
210	                mem_wr_en = 1'b1;
211	                if (write_burst_reg != 2'b00) begin
212	                    write_addr_next = write_addr_reg + (1 << write_size_reg);
213	                end
214	                write_count_next = write_count_reg - 1;
215	                if (write_count_reg > 0) begin
216	                    write_state_next = WRITE_STATE_BURST;
217	                end else begin
218	                    s_axi_wready_next = 1'b0;
219	                    if (s_axi_bready || !s_axi_bvalid) begin
220	                        s_axi_bid_next = write_id_reg;
221	                        s_axi_bvalid_next = 1'b1;
222	                        s_axi_awready_next = 1'b1;
223	                        write_state_next = WRITE_STATE_IDLE;
224	                    end else begin
225	                        write_state_next = WRITE_STATE_RESP;
226	                    end
227	                end
228	            end else begin
229	                write_state_next = WRITE_STATE_BURST;
230	            end
231	        end
232	        WRITE_STATE_RESP: begin
233	            if (s_axi_bready || !s_axi_bvalid) begin
234	                s_axi_bid_next = write_id_reg;
235	                s_axi_bvalid_next = 1'b1;
236	                s_axi_awready_next = 1'b1;
237	                write_state_next = WRITE_STATE_IDLE;
238	            end else begin
239	                write_state_next = WRITE_STATE_RESP;
240	            end
241	        end
242	    endcase
243	  end
244	
245	  always @(posedge clk) begin
246	    write_state_reg <= write_state_next;
247	
248	    write_id_reg <= write_id_next;
249	    write_addr_reg <= write_addr_next;
250	    write_count_reg <= write_count_next;
251	    write_size_reg <= write_size_next;
252	    write_burst_reg <= write_burst_next;
253	
254	    s_axi_awready_reg <= s_axi_awready_next;
255	    s_axi_wready_reg <= s_axi_wready_next;
256	    s_axi_bid_reg <= s_axi_bid_next;
257	    s_axi_bvalid_reg <= s_axi_bvalid_next;
258	
259	    for (i = 0; i < WORD_WIDTH; i = i + 1) begin
260	        if (mem_wr_en & s_axi_wstrb[i]) begin
261	            mem[write_addr_valid][WORD_SIZE*i +: WORD_SIZE] <= s_axi_wdata[WORD_SIZE*i +: WORD_SIZE];
262	        end
263	    end
264	
265	    if (rst) begin
266	        write_state_reg <= WRITE_STATE_IDLE;
267	
268	        s_axi_awready_reg <= 1'b0;
269	        s_axi_wready_reg <= 1'b0;
270	        s_axi_bvalid_reg <= 1'b0;
271	    end
272	  end
273	
274	  always @* begin
275	    read_state_next = READ_STATE_IDLE;
276	
277	    mem_rd_en = 1'b0;
278	
279	    s_axi_rid_next = s_axi_rid_reg;
280	    s_axi_rlast_next = s_axi_rlast_reg;
281	    s_axi_rvalid_next = s_axi_rvalid_reg && !(s_axi_rready || (PIPELINE_OUTPUT && !s_axi_rvalid_pipe_reg));
282	
283	    read_id_next = read_id_reg;
284	    read_addr_next = read_addr_reg;
285	    read_count_next = read_count_reg;
286	    read_size_next = read_size_reg;
287	    read_burst_next = read_burst_reg;
288	
289	    s_axi_arready_next = 1'b0;
290	
291	    case (read_state_reg)
292	        READ_STATE_IDLE: begin
293	            s_axi_arready_next = 1'b1;
294	
295	            if (s_axi_arready && s_axi_arvalid) begin
296	                read_id_next = s_axi_arid;
297	                read_addr_next = s_axi_araddr;
298	                read_count_next = s_axi_arlen;
299	                read_size_next = s_axi_arsize < $clog2(STRB_WIDTH) ? s_axi_arsize : $clog2(STRB_WIDTH);
300	                read_burst_next = s_axi_arburst;
301	
302	                s_axi_arready_next = 1'b0;
303	                read_state_next = READ_STATE_BURST;
304	            end else begin
305	                read_state_next = READ_STATE_IDLE;
306	            end
307	        end
308	        READ_STATE_BURST: begin
309	            if (s_axi_rready || (PIPELINE_OUTPUT && !s_axi_rvalid_pipe_reg) || !s_axi_rvalid_reg) begin
310	                mem_rd_en = 1'b1;
311	                s_axi_rvalid_next = 1'b1;
312	                s_axi_rid_next = read_id_reg;
313	                s_axi_rlast_next = read_count_reg == 0;
314	                if (read_burst_reg != 2'b00) begin
315	                    read_addr_next = read_addr_reg + (1 << read_size_reg);
316	                end
317	                read_count_next = read_count_reg - 1;
318	                if (read_count_reg > 0) begin
319	                    read_state_next = READ_STATE_BURST;
320	                end else begin
321	                    s_axi_arready_next = 1'b1;
322	                    read_state_next = READ_STATE_IDLE;
323	                end
324	            end else begin
325	                read_state_next = READ_STATE_BURST;
326	            end
327	        end
328	    endcase
329	  end
330	  
331	  always @(posedge clk) begin
332	    read_state_reg <= read_state_next;
333	
334	    read_id_reg <= read_id_next;
335	    read_addr_reg <= read_addr_next;
336	    read_count_reg <= read_count_next;
337	    read_size_reg <= read_size_next;
338	    read_burst_reg <= read_burst_next;
339	
340	    s_axi_arready_reg <= s_axi_arready_next;
341	    s_axi_rid_reg <= s_axi_rid_next;
342	    s_axi_rlast_reg <= s_axi_rlast_next;
343	    s_axi_rvalid_reg <= s_axi_rvalid_next;
344	
345	    if (mem_rd_en) begin
346	        s_axi_rdata_reg <= mem[read_addr_valid];
347	    end
348	
349	    if (!s_axi_rvalid_pipe_reg || s_axi_rready) begin
350	        s_axi_rid_pipe_reg <= s_axi_rid_reg;
351	        s_axi_rdata_pipe_reg <= s_axi_rdata_reg;
352	        s_axi_rlast_pipe_reg <= s_axi_rlast_reg;
353	        s_axi_rvalid_pipe_reg <= s_axi_rvalid_reg;
354	    end
355	
356	    if (rst) begin
357	        read_state_reg <= READ_STATE_IDLE;
358	
359	        s_axi_arready_reg <= 1'b0;
360	        s_axi_rvalid_reg <= 1'b0;
361	        s_axi_rvalid_pipe_reg <= 1'b0;
362	    end
363	  end
364	
365	  task display_mem;
366	    input [ADDR_WIDTH-1:0] addr;
367	    reg [VALID_ADDR_WIDTH-1:0] addr_tmp;
368	    integer k;
369	    begin
370	      k=0;
371	      addr_tmp = addr >> (ADDR_WIDTH - VALID_ADDR_WIDTH);
372	      while(k==0) begin
373	      @(posedge clk);
374	      //$display("====================================");
375	      $display("          0x%h %h",addr,mem[addr_tmp][31:0]);
376	      $display("          0x%h %h",addr+4,mem[addr_tmp][63:32]);
377	      //$display("====================================");
378	      k=1;
379	      end
380	    end
381	  endtask
382	
383	  task store_mem;
384	    input [ADDR_WIDTH-1:0] base_addr_1;
385	    input [ADDR_WIDTH-1:0] base_addr_2;
386	    input [31:0]           size_1     ;
387	    input [31:0]           size_2     ;
388	    input                  enable_1   ;
389	    input                  enable_2   ;
390	    reg [VALID_ADDR_WIDTH-1:0] addr_tmp1,addr_tmp2;
391	    integer k,l;
392	    begin
393	      addr_tmp1 = base_addr_1 >> (ADDR_WIDTH - VALID_ADDR_WIDTH);
394	      addr_tmp2 = base_addr_2 >> (ADDR_WIDTH - VALID_ADDR_WIDTH);
395	      @(posedge clk);
396	      fork begin:addr1
397	        if(enable_1)
398	          for(k=0;k<size_1/4;k=k+2) begin
399	            mem_tmp_1[k] = mem[addr_tmp1+k/2][31:0];
400	            mem_tmp_1[k+1] = mem[addr_tmp1+k/2][63:32];
401	          end
402	      end
403	      begin:addr2
404	        if(enable_2)
405	          for(l=0;l<size_2/4;l=l+2) begin
406	            mem_tmp_2[l] = mem[addr_tmp2+l/2][31:0];
407	            mem_tmp_2[l+1] = mem[addr_tmp2+l/2][63:32];
408	          end
409	      end
410	      join
411	    end
412	  endtask
413	
414	endmodule
415	
416	`resetall
