`timescale 1ns / 1ps

module gen_clk(
  output clk
  );

  localparam PERIOD = 10.0;

  reg clk_r;
  initial begin
   clk_r = 1'b0;
   while(1) begin
    #(PERIOD/2) clk_r = ~clk_r;
   end
  end

  assign clk = clk_r;

endmodule

module gen_rst(
  output rst_n,
  input  clk
  );
  //-----------------------
  localparam RST_CYCLE_N = 2;

  reg rst_n_r;
  initial begin
   rst_n_r = 0;
   repeat(RST_CYCLE_N)
   @(posedge clk)
   rst_n_r = 1'b1;
  end

  assign rst_n = rst_n_r;

endmodule
